const assistValid=valid,assistRender=render,assistOpen=openJournal,assistSave=save;
const assistBuild=JournalCore.build;
JournalCore.build=function(d,f,context,id){const old=d.trades.find(t=>t.id===context.tradeId);if(old?.charges?.length&&f.asset!==old.asset)throw Error('มี Funding/Swap รายวันแล้ว ต้องจัดการค่าใช้จ่ายเดิมก่อนเปลี่ยนสัญญาและสกุลเงิน');return assistBuild(d,f,context,id)};
valid=function(d){try{return assistValid(d)&&AssistCore.valid({...d,accounts:d.accounts||defaultAccounts()})&&d.trades.every(t=>t.currentStop==null||Number.isFinite(t.currentStop)&&t.currentStop>0)}catch{return false}};
// Preserve account presets when editing account names through the original form.
function preset(accountId,asset){return (data.portfolioDefaults||[]).find(r=>r.accountId===accountId&&r.asset===asset)}
$('#manage-accounts').insertAdjacentHTML('afterend','<button id="manage-defaults" class="text-button">ค่าประจำพอร์ต</button>');
function openDefaults(accountId=selectedAccount(),asset='XAUUSD'){
 if(!featureAllowed())return;const r=preset(accountId,asset)||{strategy:'ทั่วไป',side:'Long',quantity:.01,multiplier:1,fee:0},fixed=JournalCore.fixedMultiplier(data,accountId,asset);
 if(!wfShow('ค่าประจำพอร์ต',`<form id="defaults-form"><div class="form-grid">${options('พอร์ต','accountId',[['','เลือกพอร์ต'],...accounts().map(a=>[a.id,accountName(a.id)])],accountId)}${options('สัญญา','asset',['XAUUSD','BTCUSDT','BTCUSD'],asset)}${options('กลยุทธ์','strategy',['ทั่วไป','Grid','Rebalance'],r.strategy)}${options('ทิศทางเริ่มต้น','side',['Long','Short'],r.side)}${field('จำนวนเริ่มต้น Lot / สัญญา','quantity','number',r.quantity,'required min="0.000000000001" step="any"')}${field('ตัวคูณสัญญา','multiplier','number',fixed??r.multiplier,'required min="0.000000000001" step="any" '+(fixed?'readonly':''))}${field('ค่าธรรมเนียมเริ่มต้น ('+JournalCore.unit(asset)+')','fee','number',r.fee,'required min="0" step="any"')}</div><p>จำแยกตามพอร์ตและสัญญา สกุลผลกำไรใช้ ${JournalCore.unit(asset)} อัตโนมัติ เติมเฉพาะรายการใหม่ ไม่แก้ประวัติหรือแผนเดิม ราคาและวันเวลาไม่ถูกจำ</p><button type="submit" class="primary">จำค่าประจำพอร์ต</button></form>`))return;
 const form=$('#defaults-form');for(const key of ['accountId','asset'])form.elements[key].onchange=()=>{const a=form.elements.accountId.value,s=form.elements.asset.value;openDefaults(a,s)};
 form.onsubmit=e=>{e.preventDefault();const f=Object.fromEntries(new FormData(form)),r={...f,id:f.accountId+'|'+f.asset,currency:JournalCore.unit(f.asset)};for(const k of ['quantity','multiplier','fee'])r[k]=Number(r[k]);r.multiplier=JournalCore.fixedMultiplier(data,r.accountId,r.asset)??r.multiplier;wfCommit(()=>({...data,portfolioDefaults:[...(data.portfolioDefaults||[]).filter(p=>p.id!==r.id),r]}),()=>$('#workflow-dialog').close())};
}
$('#manage-defaults').onclick=()=>openDefaults();
function applyPreset(allowFallback=true){
 if(journalContext.tradeId||journalContext.planId)return;const form=$('#journal-form');if(form.elements.linkId?.value)return;let r=preset(form.elements.accountId.value,form.elements.asset.value);if(!r&&allowFallback){const saved=(data.portfolioDefaults||[]).filter(p=>p.accountId===form.elements.accountId.value);if(saved.length===1){r=saved[0];form.elements.asset.value=r.asset}}if(!r)return;
 for(const k of ['strategy','side','quantity','fee','multiplier'])form.elements[k].value=r[k];form.elements.planMultiplier.value=r.multiplier;updateJournalForm();$('#journal-units').textContent+=' · เติมค่าประจำพอร์ตแล้ว ตรวจให้ตรงรายการจริง';
}
openJournal=function(kind,id){assistOpen(kind,id);if(!$('#journal-dialog').open)return;if(!id)applyPreset();const t=data.trades.find(t=>t.id===id);if(t)$('#journal-related').insertAdjacentHTML('afterbegin',`<button class="text-button" type="button" data-assist-stop="${esc(id)}">SL ปัจจุบัน / ความเสี่ยง</button> · <button class="text-button" type="button" data-assist-charge="${esc(id)}">Funding / Swap ตามวันที่</button>`)};
$('#journal-form').addEventListener('change',e=>{if(['accountId','asset'].includes(e.target.name)&&!journalContext.tradeId&&!journalContext.planId){if((preset(e.currentTarget.elements.accountId.value,e.currentTarget.elements.asset.value)||e.target.name==='accountId'&&(data.portfolioDefaults||[]).some(r=>r.accountId===e.currentTarget.elements.accountId.value))&&confirm('เติมค่าประจำพอร์ตแทนค่าเริ่มต้นในฟอร์มนี้หรือไม่?'))applyPreset(e.target.name==='accountId')}});
function closeJournalForTool(){if($('#journal-dialog').open){if(!wfDiscard($('#journal-dialog')))return false;$('#journal-dialog').close()}return true}
function openStop(id){
 if(!featureAllowed()||!closeJournalForTool())return;const t=data.trades.find(r=>r.id===id);if(!t)return;const r=AssistCore.risks({...data,trades:[{...t,exit:null}]})[0];
 if(!wfShow('SL ปัจจุบัน',`<p>${esc(t.asset)} · ${esc(accountName(t.accountId))}</p><form id="stop-form">${field('ราคา Stop Loss ปัจจุบัน','stop','number',t.currentStop??r.stop??'','min="0.000000000001" step="any"')}<p>ใช้สรุปความเสี่ยงของจำนวนที่ยังถือ ไม่แก้แผนเดิมหรือ 1R เริ่มต้น เว้นว่างเพื่อล้างค่าปัจจุบันและกลับไปใช้ SL ตามแผน</p><button type="submit" class="primary">บันทึก SL</button></form>`))return;
 $('#stop-form').onsubmit=e=>{e.preventDefault();const value=e.target.elements.stop.value;wfCommit(()=>({...data,trades:data.trades.map(r=>r.id===id?{...r,currentStop:value===''?null:Number(value)}:r)}),()=>$('#workflow-dialog').close())};
}
function openCharges(id,editId){
 if(!featureAllowed()||!closeJournalForTool())return;const t=data.trades.find(r=>r.id===id);if(!t)return;const edit=(t.charges||[]).find(c=>c.id===editId);
 if(!wfShow('Funding / Swap ตามวันที่',`<p>${esc(t.asset)} · ${esc(accountName(t.accountId))} · ${t.currency}</p><p>รับรู้ตามวันเวลาที่หักจริง จ่ายเป็นบวก รับเป็นลบ ห้ามกรอกยอดเดียวกันซ้ำใน Funding สะสมหรือช่อง Funding ของไม้เข้า/ปิด หากมีแบบเดิมต้องแก้ให้เป็น 0 ก่อนย้ายมาบันทึกแบบรายวัน</p>${gridTable(['เวลาไทย','ประเภท','จ่าย + / รับ −',''],(t.charges||[]).map(c=>`<tr><td>${esc(c.time.replace('T',' '))}</td><td>${esc(c.type)}</td><td>${money(c.amount,t.currency)}</td><td><button data-charge-edit="${esc(c.id)}">แก้ไข</button><button data-charge-remove="${esc(c.id)}">ลบ</button></td></tr>`))}<form id="charge-form"><div class="form-grid">${options('ประเภท','type',['Funding','Swap'],edit?.type||'Swap')}${field('เวลาไทยที่หักจริง','time','datetime-local',edit?.time||date()+'T12:00','required')}${field('ยอด ('+t.currency+')','amount','number',edit?.amount??'','required step="any"')}${textarea('หมายเหตุ','note',edit?.note||'')}</div><button type="submit" class="primary">บันทึกค่าใช้จ่าย</button></form>`))return;
 $('#charge-form').onsubmit=e=>{e.preventDefault();const f=Object.fromEntries(new FormData(e.target)),c={...f,amount:Number(f.amount),id:editId||crypto.randomUUID()};wfCommit(()=>({...data,trades:data.trades.map(r=>r.id===id?AssistCore.addCharge(r,c):r)}),()=>openCharges(id))};
 $$('[data-charge-edit]').forEach(b=>b.onclick=()=>openCharges(id,b.dataset.chargeEdit));$$('[data-charge-remove]').forEach(b=>b.onclick=()=>{if(confirm('ลบค่าใช้จ่ายนี้และคำนวณผลใหม่?'))wfCommit(()=>({...data,trades:data.trades.map(r=>r.id===id?AssistCore.addCharge(r,null,b.dataset.chargeRemove):r)}),()=>openCharges(id))});
}
document.addEventListener('click',e=>{const b=e.target.closest('button');if(!b)return;if(b.dataset.assistStop)openStop(b.dataset.assistStop);if(b.dataset.assistCharge)openCharges(b.dataset.assistCharge);if(b.dataset.assistEdit)openJournal('trade',b.dataset.assistEdit);if(b.dataset.assistReview)linkedReviews(b.dataset.assistReview)});
function assistPanels(){
 const visible=t=>t.currency===currency&&accountMatches(t),tasks=AssistCore.inbox(data,date()).filter(i=>visible(i.trade)),risks=AssistCore.risks(data).filter(visible),known=risks.filter(r=>r.risk!==null),unknown=risks.length-known.length;
 const groups=new Map();for(const r of known)groups.set(r.accountId,(groups.get(r.accountId)||0)+r.risk);
 const taskList=tasks.slice(0,20).map(i=>`<li>${esc(i.trade.asset)} · ${esc(accountName(i.trade.accountId))} — ${esc(i.label)} <button class="text-button" data-assist-${i.kind}="${esc(i.trade.id)}">ตรวจรายการ</button></li>`).join('');
 return `<article class="panel" id="assist-inbox"><details ${tasks.length?'open':''}><summary>รายการที่ต้องตรวจ (${tasks.length})</summary><p>ตามพอร์ตและสกุลเงินที่เลือก รวมทุกกลยุทธ์ · เป็นรายการช่วยตรวจ ไม่ได้ยืนยันว่าข้อมูลผิด</p>${taskList?'<ul>'+taskList+'</ul>':'<p>ไม่มีรายการต้องตรวจตามเกณฑ์นี้</p>'}${tasks.length>20?'<p>แสดง 20 จุดแรก แก้แล้วรายการถัดไปจะแสดงเอง</p>':''}${$('#account-filter').value!=='all'?'<details><summary>ตรวจส่วนต่าง Balance</summary>'+reconcilePanel()+'</details>':''}</details></article><article class="panel" id="assist-risk"><details><summary>ความเสี่ยงสถานะเปิดตาม SL · ${money(known.reduce((s,r)=>s+r.risk,0),currency)} ${currency}${unknown?' + '+unknown+' รายการที่ยังคำนวณไม่ได้':''}</summary><p>ขาดทุนจากต้นทุนเฉลี่ยส่วนที่เหลือถึง SL รวมแยกพอร์ต ไม่หักล้าง Long/Short ไม่ใช่ขาดทุนเพิ่มจากราคาปัจจุบัน และไม่รวมค่าธรรมเนียมหรือ Slippage ยอดรวมอาจไม่ครบถ้ายังมีรายการไม่มี SL</p>${gridTable(['พอร์ต','ขาดทุนตาม SL ที่ทราบ'],[...groups].map(([id,sum])=>`<tr><td>${esc(accountName(id))}</td><td>${money(sum)} ${currency}</td></tr>`))}${gridTable(['สินทรัพย์','SL','จำนวนเหลือ','ขาดทุนตาม SL',''],risks.map(r=>`<tr><td>${esc(r.asset)} ${esc(r.side)}</td><td>${r.stop??'—'}</td><td>${qty(r.left)}</td><td>${r.risk===null?'ไม่ทราบ':money(r.risk)}</td><td><button data-assist-stop="${esc(r.id)}">แก้ SL</button></td></tr>`))}</details></article>`;
}
render=function(){assistRender();$('#assist-inbox')?.remove();$('#assist-risk')?.remove();if(view==='analytics'&&insightTab==='summary')$('#feature-page').insertAdjacentHTML('afterbegin',assistPanels())};
$('#lean-data-tools').insertAdjacentHTML('beforeend','<button class="text-button" id="import-exness">นำเข้า Exness CSV</button>');
function openExness(){
 if(!featureAllowed())return;let source=null,preview=null,revision=null,sequence=0;
 if(!wfShow('นำเข้า Exness CSV — XAUUSD',`<p>สำหรับรายงานที่หนึ่งแถวเป็นตำแหน่งที่ปิดครบ มีราคา/เวลาเข้าและออกในแถวเดียว บัญชี USD ปกติและจำนวนเป็น Lot เท่านั้น ไม่รองรับบัญชี Cent หรือประวัติ Deals แยกขา</p><form id="exness-file"><div class="form-grid">${options('พอร์ต Exness ปลายทาง','accountId',[['','เลือกพอร์ต'],...accounts().filter(a=>a.broker==='Exness').map(a=>[a.id,accountName(a.id)])],'')}<label>CSV (ไม่เกิน 1 MB / 500 แถว)<input type="file" name="file" accept=".csv,text/csv" required></label></div><button type="submit">อ่านหัวคอลัมน์</button></form><div id="exness-map"></div><div id="exness-preview"></div><button id="exness-confirm" class="primary" disabled>ยืนยันนำเข้า</button>`))return;
 const reset=()=>{preview=null;$('#exness-confirm').disabled=true;$('#exness-preview').textContent='';};
 $('#exness-file').onchange=()=>{sequence++;source=null;reset();$('#exness-map').innerHTML=''};
 $('#exness-file').onsubmit=async e=>{e.preventDefault();const seq=++sequence,form=e.target;reset();try{const file=form.elements.file.files[0];if(!file||file.size>1000000)throw Error('เลือกไฟล์ขนาดไม่เกิน 1 MB');const text=await file.text();if(seq!==sequence||!form.isConnected)return;source=WorkflowCore.csv(text);const cols=Object.keys(source[0]);
  const fields={ticket:['รหัสตำแหน่ง',['position','ticket','order','position id']],symbol:['สัญลักษณ์',['symbol','instrument']],side:['Buy / Sell',['type','side']],quantity:['จำนวน Lot',['volume','lots','quantity']],entry:['ราคาเข้า',['open price','opening price']],exit:['ราคาออก',['close price','closing price']],opened:['เวลาเปิด',['open time','opening time']],closed:['เวลาปิด',['close time','closing time']],fee:['Commission (ไม่บังคับ)',['commission']],swap:['Swap (ไม่บังคับ)',['swap']],net:['กำไรสุทธิหลังค่าใช้จ่าย (ไม่บังคับ)',[]]};
  $('#exness-map').innerHTML=`<form id="exness-mapping"><p>ตรวจการจับคู่ทุกช่อง โดยเฉพาะราคาเข้าและราคาออก</p><div class="form-grid">${Object.entries(fields).map(([key,[label,aliases]])=>options(label,key,[['','ไม่เลือก'],...cols],cols.find(c=>aliases.includes(c.trim().toLowerCase()))||'')).join('')}${options('ค่าสัญลักษณ์ที่ยืนยันว่าเป็น XAUUSD','gold',[['','เลือกหลังจับคู่คอลัมน์ Symbol']],'')}${options('รูปแบบวันที่','format',[['ymd','ปี-เดือน-วัน เวลา'],['dmy','วัน-เดือน-ปี เวลา']],'ymd')}${field('เขตเวลาในไฟล์ (UTC offset)','offset','number',0,'required min="-12" max="14" step="0.25"')}${options('เครื่องหมาย Commission / Swap','sign',[['signed','ไฟล์ใช้ลบ = จ่าย / บวก = รับ'],['cost','ไฟล์ใช้บวก = จ่าย / ลบ = รับ']],'signed')}</div><label><input type="checkbox" name="confirm" required>ยืนยันเป็นบัญชี USD ปกติ จำนวน Lot และหนึ่งแถวเป็นตำแหน่งที่ปิดครบ (ไม่ใช่ Deals แยกขา)</label><p>เวลาในไฟล์จะแปลงเป็นเวลาไทย ไม่เดาเขตเวลา · ช่องกำไรสุทธิใช้ตรวจสอบได้ ห้ามจับคู่กับกำไรก่อน Commission/Swap</p><button type="submit">ตรวจตัวอย่าง</button></form>`;
  const mapping=$('#exness-mapping'),refreshSymbols=()=>{const selected=mapping.elements.symbol.value;mapping.elements.gold.innerHTML='<option value="">เลือกสัญลักษณ์ทอง</option>'+[...new Set(source.map(r=>r[selected]).filter(Boolean))].map(v=>`<option value="${esc(v)}">${esc(v)}</option>`).join('')};refreshSymbols();mapping.onchange=e=>{reset();if(e.target.name==='symbol')refreshSymbols()};
  mapping.onsubmit=e=>{e.preventDefault();reset();try{const values=Object.fromEntries(new FormData(mapping)),accountId=form.elements.accountId.value;if(!values.gold)throw Error('เลือกสัญลักษณ์ทอง');if(!/^XAUUSD[a-z]*$/i.test(values.gold))throw Error('รองรับสัญลักษณ์ XAUUSD และ suffix ตัวอักษรเท่านั้น');const map=Object.fromEntries(Object.keys(fields).map(k=>[k,values[k]]));preview=AssistCore.exness({...data,accounts:accounts()},source,map,{accountId,symbol:values.gold,format:values.format,offset:Number(values.offset),sign:values.sign},()=>crypto.randomUUID());revision=cloudRevision;if(!valid(preview.next))preview.issues.push('ข้อมูลรวมไม่ผ่านการตรวจสอบ');$('#exness-preview').innerHTML=`<p>เพิ่ม ${preview.rows.length} · ซ้ำ ${preview.duplicates} · ข้ามสัญลักษณ์อื่น ${preview.skipped} · ผิดพลาด ${preview.issues.length}</p><p>${preview.issues.map(esc).join('<br>')}</p>${gridTable(['วันที่','สัญญา','Lot','เข้า → ออก','สุทธิ USD'],preview.rows.slice(0,30).map(r=>`<tr><td>${r.date}</td><td>${r.asset} ${r.side}</td><td>${qty(r.quantity)}</td><td>${r.entry} → ${r.exit}</td><td>${money(pnl(r),'USD')}</td></tr>`))}<p>แสดง 30 แถวแรก ตรวจยอดกับรายงานก่อนยืนยัน ไม่มีการเขียนทับรายการเดิม</p>`;$('#exness-confirm').disabled=!!preview.issues.length||!preview.rows.length}catch(err){$('#workflow-error').textContent=err.message}};
 }catch(err){$('#workflow-error').textContent=err.message}};
 $('#exness-confirm').onclick=()=>{if(!preview||preview.issues.length)return;if(revision!==cloudRevision){$('#workflow-error').textContent='ข้อมูลเปลี่ยนแล้ว ต้องตรวจตัวอย่างใหม่';return}wfCommit(()=>preview.next,()=>$('#workflow-dialog').close())};
}
$('#import-exness').onclick=openExness;
render();
